import React, { useState } from 'react';

interface PowerFlowDiagramProps {
  pv: number;
  load: number;
  bess: number;
  genset: number;
  soc: number;
  blackout: boolean;
}

// Composant pour les icônes SVG
const SVGIcon: React.FC<{ 
  name: string; 
  className?: string; 
  size?: number;
}> = ({ name, className = '', size = 48 }) => {
  const icons: { [key: string]: string } = {
    battery: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="2" y="7" width="16" height="10" rx="2" ry="2"/>
      <line x1="6" y1="11" x2="6" y2="13"/>
      <line x1="10" y1="11" x2="10" y2="13"/>
      <line x1="14" y1="11" x2="14" y2="13"/>
      <line x1="18" y1="11" x2="18" y2="13"/>
    </svg>`,
    solar: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <circle cx="12" cy="12" r="5"/>
      <line x1="12" y1="1" x2="12" y2="3"/>
      <line x1="12" y1="21" x2="12" y2="23"/>
      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/>
      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/>
      <line x1="1" y1="12" x2="3" y2="12"/>
      <line x1="21" y1="12" x2="23" y2="12"/>
      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/>
      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>
    </svg>`,
    generator: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>
      <line x1="8" y1="21" x2="16" y2="21"/>
      <line x1="12" y1="17" x2="12" y2="21"/>
      <circle cx="12" cy="10" r="2"/>
      <path d="M8 10h8"/>
    </svg>`,
    grid: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
      <line x1="9" y1="9" x2="15" y2="15"/>
      <line x1="15" y1="9" x2="9" y2="15"/>
      <circle cx="12" cy="12" r="1"/>
    </svg>`,
    load: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>
      <line x1="8" y1="21" x2="16" y2="21"/>
      <line x1="12" y1="17" x2="12" y2="21"/>
      <path d="M7 7h10v4H7z"/>
      <path d="M7 11h10v4H7z"/>
    </svg>`,
    warning: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
      <line x1="12" y1="9" x2="12" y2="13"/>
      <line x1="12" y1="17" x2="12.01" y2="17"/>
    </svg>`,
    charging: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <path d="M18 7h1a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-1"/>
      <path d="M6 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h1"/>
      <line x1="12" y1="11" x2="12" y2="13"/>
      <line x1="12" y1="7" x2="12" y2="9"/>
      <line x1="12" y1="15" x2="12" y2="17"/>
    </svg>`,
    discharging: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <path d="M6 17h1a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2H6"/>
      <path d="M18 17h1a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-1"/>
      <line x1="12" y1="11" x2="12" y2="13"/>
      <line x1="12" y1="7" x2="12" y2="9"/>
      <line x1="12" y1="15" x2="12" y2="17"/>
    </svg>`
  };

  return (
    <div 
      className={`inline-flex items-center justify-center ${className}`}
      style={{ width: size, height: size }}
      dangerouslySetInnerHTML={{ __html: icons[name] || '' }}
    />
  );
};


const PowerFlowDiagram: React.FC<PowerFlowDiagramProps> = ({
  pv,
  load,
  bess,
  genset,
  soc,
  blackout
}) => {
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Layout explicite avec coordonnées fixes
  const layout = {
    center: { x: 400, y: 300 }, // Centre du réseau
    components: {
      pv: { x: 400, y: 150 },      // PV en haut
      bess: { x: 250, y: 300 },    // BESS à gauche
      genset: { x: 550, y: 300 },  // Genset à droite
      load: { x: 400, y: 450 }     // Load en bas
    }
  };

  // Couleurs selon le mode
  const colors = {
    light: {
      background: 'bg-gradient-to-br from-slate-50 to-blue-50',
      card: 'bg-white',
      text: 'text-gray-800',
      textSecondary: 'text-gray-600',
      border: 'border-gray-200',
      pv: 'text-yellow-600',
      bess: bess > 0 ? 'text-green-600' : bess < 0 ? 'text-red-600' : 'text-gray-500',
      genset: 'text-blue-600',
      load: 'text-orange-600',
      grid: blackout ? 'text-red-600' : 'text-green-600',
      flow: {
        pv: '#f59e0b',
        bess: bess > 0 ? '#10b981' : '#ef4444',
        genset: '#3b82f6',
        load: '#f97316'
      }
    },
    dark: {
      background: 'bg-gradient-to-br from-gray-900 to-blue-900',
      card: 'bg-gray-800',
      text: 'text-gray-100',
      textSecondary: 'text-gray-300',
      border: 'border-gray-700',
      pv: 'text-yellow-400',
      bess: bess > 0 ? 'text-green-400' : bess < 0 ? 'text-red-400' : 'text-gray-400',
      genset: 'text-blue-400',
      load: 'text-orange-400',
      grid: blackout ? 'text-red-400' : 'text-green-400',
      flow: {
        pv: '#fbbf24',
        bess: bess > 0 ? '#34d399' : '#f87171',
        genset: '#60a5fa',
        load: '#fb923c'
      }
    }
  };

  const theme = isDarkMode ? colors.dark : colors.light;

  // Fonction pour déterminer si une flèche doit être affichée
  const shouldShowFlow = (power: number) => {
    return Math.abs(power) > 0.1;
  };

  // Fonction pour créer une ligne SVG avec animation
  const createFlowLine = (from: { x: number; y: number }, to: { x: number; y: number }, color: string, intensity: number, direction: 'in' | 'out') => {
    const length = Math.sqrt(Math.pow(to.x - from.x, 2) + Math.pow(to.y - from.y, 2));
    const angle = Math.atan2(to.y - from.y, to.x - from.x) * 180 / Math.PI;
    const opacity = Math.min(100, Math.max(30, intensity * 15)) / 100;

    return (
      <g key={`flow-${from.x}-${from.y}`}>
        {/* Ligne de fond */}
        <line
          x1={from.x}
          y1={from.y}
          x2={to.x}
          y2={to.y}
          stroke="rgba(0,0,0,0.1)"
          strokeWidth="4"
          opacity="0.3"
        />

        {/* Flux animé */}
        <line
          x1={from.x}
          y1={from.y}
          x2={to.x}
          y2={to.y}
          stroke={color}
          strokeWidth="6"
          opacity={opacity}
          strokeDasharray="10 5"
          strokeDashoffset={direction === 'out' ? "0" : "15"}
        >
          <animate
            attributeName="stroke-dashoffset"
            values={direction === 'out' ? "0;-15" : "15;0"}
            dur="2s"
            repeatCount="indefinite"
          />
        </line>

        {/* Particule animée */}
        <circle
          r="3"
          fill={color}
          opacity={opacity}
        >
          <animateMotion
            dur="2s"
            repeatCount="indefinite"
            path={`M ${from.x} ${from.y} L ${to.x} ${to.y}`}
            rotate="auto"
          />
        </circle>

        {/* Flèche de direction */}
        <polygon
          points={`${to.x},${to.y} ${to.x - 8},${to.y - 4} ${to.x - 8},${to.y + 4}`}
          fill={color}
          opacity={opacity}
          transform={`rotate(${angle} ${to.x} ${to.y})`}
        />
      </g>
    );
  };

  return (
    <>
      {/* Styles CSS pour les animations */}
      <style dangerouslySetInnerHTML={{
        __html: `
          @keyframes flow-forward {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
          }
          @keyframes flow-backward {
            0% { transform: translateX(100%); }
            100% { transform: translateX(-100%); }
          }
          @keyframes flow-bidirectional {
            0%, 100% { transform: translateX(-50%); }
            50% { transform: translateX(50%); }
          }
          @keyframes particle-flow-forward {
            0% { left: -8px; }
            100% { left: calc(100% + 8px); }
          }
          @keyframes particle-flow-backward {
            0% { left: calc(100% + 8px); }
            100% { left: -8px; }
          }
          @keyframes particle-flow-bidirectional {
            0%, 100% { left: 0%; }
            50% { left: calc(100% - 8px); }
          }
          @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 20px currentColor; }
            50% { box-shadow: 0 0 40px currentColor; }
          }
          @keyframes rotate-slow {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
          }
        `
      }} />

      <div className={`${theme.background} rounded-2xl shadow-2xl border ${theme.border} p-8 mt-8 transition-all duration-500`}>
        {/* Header avec toggle dark mode */}
        <div className="flex justify-between items-center mb-8">
          <h3 className={`text-3xl font-bold ${theme.text} flex items-center gap-3`}>
            <SVGIcon name="grid" size={32} className={theme.grid} />
            Flux de Puissance du Microgrid
          </h3>
          <button
            onClick={() => setIsDarkMode(!isDarkMode)}
            className={`p-3 rounded-xl ${theme.card} border ${theme.border} hover:shadow-lg transition-all duration-300`}
            title="Basculer le mode clair/sombre"
          >
            <SVGIcon 
              name={isDarkMode ? "solar" : "battery"} 
              size={24} 
              className={theme.textSecondary} 
            />
          </button>
        </div>

        {/* Layout SVG avec positionnement explicite */}
        <div className="relative w-full h-[600px] overflow-hidden">
          <svg width="100%" height="100%" className="absolute inset-0">
            {/* Lignes de flux SVG */}
            {shouldShowFlow(pv) && createFlowLine(
              layout.components.pv, 
              layout.center, 
              theme.flow.pv, 
              Math.abs(pv) / 10, 
              'out'
            )}

            {shouldShowFlow(bess) && createFlowLine(
              layout.center, 
              layout.components.bess, 
              theme.flow.bess, 
              Math.abs(bess) / 10, 
              bess > 0 ? 'in' : 'out'
            )}

            {shouldShowFlow(genset) && createFlowLine(
              layout.components.genset, 
              layout.center, 
              theme.flow.genset, 
              Math.abs(genset) / 10, 
              'out'
            )}

            {shouldShowFlow(load) && createFlowLine(
              layout.center, 
              layout.components.load, 
              theme.flow.load, 
              Math.abs(load) / 10, 
              'out'
            )}
          </svg>

          {/* Composants positionnés absolument */}

          {/* PV (en haut) */}
          <div 
            className={`absolute text-center p-4 rounded-2xl ${theme.card} border ${theme.border} shadow-lg hover:shadow-xl transition-all duration-300 w-48`}
            style={{ 
              left: layout.components.pv.x - 96, 
              top: layout.components.pv.y - 60 
            }}
          >
            <div className="mb-3">
              <SVGIcon 
                name="solar" 
                size={48} 
                className={`${theme.pv} animate-pulse`} 
              />
            </div>
            <div className={`text-lg font-bold ${theme.text}`}>PV</div>
            <div className={`text-2xl font-bold ${theme.pv} mb-1`}>{pv.toFixed(1)} kW</div>
            <div className={`text-xs ${theme.textSecondary}`}>Production solaire</div>
          </div>

          {/* BESS (à gauche) */}
          <div 
            className={`absolute text-center p-4 rounded-2xl ${theme.card} border ${theme.border} shadow-lg hover:shadow-xl transition-all duration-300 w-48`}
            style={{ 
              left: layout.components.bess.x - 96, 
              top: layout.components.bess.y - 60 
            }}
          >
            <div className="mb-3">
              <SVGIcon 
                name={bess > 0 ? "charging" : bess < 0 ? "discharging" : "battery"} 
                size={48} 
                className={`${theme.bess} ${bess !== 0 ? 'animate-pulse' : ''}`} 
              />
            </div>
            <div className={`text-lg font-bold ${theme.text}`}>BESS</div>
            <div className={`text-2xl font-bold ${theme.bess} mb-1`}>
              {Math.abs(bess).toFixed(1)} kW
            </div>
            <div className={`text-xs ${theme.textSecondary}`}>
              SOC: {soc.toFixed(1)}%
            </div>
            <div className={`text-xs ${theme.textSecondary}`}>
              {bess > 0 ? 'Charge' : bess < 0 ? 'Décharge' : 'Neutre'}
            </div>
          </div>

          {/* Réseau (au centre) */}
          <div 
            className={`absolute text-center p-4 rounded-2xl ${theme.card} border ${theme.border} shadow-lg hover:shadow-xl transition-all duration-300 w-48 ${blackout ? 'ring-2 ring-red-500' : 'ring-2 ring-green-500'}`}
            style={{ 
              left: layout.center.x - 96, 
              top: layout.center.y - 60 
            }}
          >
            <div className="mb-3">
              <SVGIcon 
                name={blackout ? "warning" : "grid"} 
                size={48} 
                className={`${theme.grid} ${blackout ? 'animate-pulse' : ''}`} 
              />
            </div>
            <div className={`text-lg font-bold ${theme.text}`}>Réseau</div>
            <div className={`text-xl font-bold ${theme.grid} mb-1`}>
              {blackout ? 'Blackout' : 'Stable'}
            </div>
            <div className={`text-xs ${theme.textSecondary}`}>
              {blackout ? 'Panne réseau' : 'Réseau connecté'}
            </div>
          </div>

          {/* Genset (à droite) */}
          <div 
            className={`absolute text-center p-4 rounded-2xl ${theme.card} border ${theme.border} shadow-lg hover:shadow-xl transition-all duration-300 w-48`}
            style={{ 
              left: layout.components.genset.x - 96, 
              top: layout.components.genset.y - 60 
            }}
          >
            <div className="mb-3">
              <SVGIcon 
                name="generator" 
                size={48} 
                className={`${theme.genset} ${genset > 0 ? 'animate-pulse' : ''}`} 
              />
            </div>
            <div className={`text-lg font-bold ${theme.text}`}>Genset</div>
            <div className={`text-2xl font-bold ${theme.genset} mb-1`}>{genset.toFixed(1)} kW</div>
            <div className={`text-xs ${theme.textSecondary}`}>Production de secours</div>
          </div>

          {/* Load (en bas) */}
          <div 
            className={`absolute text-center p-4 rounded-2xl ${theme.card} border ${theme.border} shadow-lg hover:shadow-xl transition-all duration-300 w-48`}
            style={{ 
              left: layout.components.load.x - 96, 
              top: layout.components.load.y - 60 
            }}
          >
            <div className="mb-3">
              <SVGIcon 
                name="load" 
                size={48} 
                className={`${theme.load}`} 
              />
            </div>
            <div className={`text-lg font-bold ${theme.text}`}>Charge</div>
            <div className={`text-2xl font-bold ${theme.load} mb-1`}>{load.toFixed(1)} kW</div>
            <div className={`text-xs ${theme.textSecondary}`}>Consommation</div>
          </div>
        </div>
      </div>
    </>
  );
};

export default PowerFlowDiagram;
